document.addEventListener('DOMContentLoaded',()=>{const wrap=document.createElement('div');wrap.className='briefing';wrap.innerHTML='<div class="briefing-card"><span class="eyebrow">ANTES DE COMEÇAR</span><h2>Vamos montar uma viagem com a sua cara.</h2><p>São quatro respostas rápidas para o app não sugerir um roteiro impossível.</p><label>Quantos dias você fica em Angra?<select id="days"><option value="2">2 dias</option><option value="3" selected>3 dias</option><option value="4">4 dias</option><option value="5">5 dias ou mais</option></select></label><label>Onde você vai ficar?<select id="stay"><option>Centro de Angra</option><option>Abraão · Ilha Grande</option><option>Conceição de Jacareí</option><option>Ainda não decidi</option></select></label><label>Você já tem hospedagem?<select id="hotel"><option>Sim, já reservei</option><option>Ainda estou procurando</option></select></label><label>Quer receber ajuda com passeio de barco?<select id="boat"><option>Sim, quero falar com um parceiro</option><option>Vou resolver por conta própria</option><option>Ainda não sei</option></select></label><button id="startBriefing">Montar meu roteiro</button></div>';document.body.appendChild(wrap);const saved=localStorage.getItem('angra-briefing');if(saved)wrap.remove();document.querySelector('#startBriefing').onclick=()=>{const profile={days:days.value,stay:stay.value,hotel:hotel.value,boat:boat.value};localStorage.setItem('angra-briefing',JSON.stringify(profile));wrap.remove();const side=document.querySelector('.side .small');if(side)side.textContent=`Roteiro de ${profile.days} dias · base em ${profile.stay}`;if(profile.boat.startsWith('Sim')){const b=document.createElement('button');b.className='partner-cta';b.textContent='Quero falar sobre passeio de barco';b.onclick=()=>alert('Na próxima etapa vamos conectar você a um parceiro de passeio.');document.querySelector('.side').appendChild(b)}};const css=document.createElement('style');css.textContent='.briefing{position:fixed;inset:0;background:rgba(20,43,58,.72);z-index:20;display:grid;place-items:center;padding:18px}.briefing-card{background:#f7f4ec;border-radius:26px;padding:26px;max-width:460px;width:100%;box-shadow:0 25px 80px rgba(20,43,58,.3)}.briefing-card h2{font-size:35px;line-height:1;letter-spacing:-.05em;margin:9px 0}.briefing-card p{color:#66808b;line-height:1.45}.briefing-card label{display:block;font-size:13px;font-weight:700;margin:15px 0}.briefing-card select{display:block;width:100%;margin-top:7px;padding:12px;border:1px solid #d8e5e1;border-radius:11px;background:#fff;color:#142b3a;font-size:14px}.briefing-card button,.partner-cta{border:0;background:#f26b4f;color:#fff;width:100%;padding:14px;border-radius:12px;font-weight:700;cursor:pointer;margin-top:12px}.partner-cta{background:#142b3a;margin-top:16px}';document.head.appendChild(css)});
